package ir.sejadalmas.salesagent;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class Api { String base,token=""; Api(String b,String t){base=b.replaceAll("/+$","");token=t==null?"":t;}
 JSONObject call(String path,String method,JSONObject body)throws Exception{URL u=new URL(base+"/sales-mobile-api/"+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Content-Type","application/json; charset=utf-8");if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();StringBuilder s=new StringBuilder();if(in!=null)try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String x;while((x=r.readLine())!=null)s.append(x);}if(s.length()==0)return new JSONObject().put("success",false).put("message","پاسخ خالی از سرور");return new JSONObject(s.toString()); }
}
